internal sealed class StateApproximationS3QuantumAlgebraStateApproximationTauCetiAnalysisCStarAlgebraContinuousFunctionalCalculusKaplanskyDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Self-adjoint truncation by functional calculus", H("Self-adjoint truncation by functional calculus"), Blocks(
        Paragraph(Text("The real function f(t)=2t/(1+t squared) maps the real line into the closed unit interval in absolute value. Its right inverse there is g(s)=s/(1+sqrt(1-s squared)). Functional calculus gives norm(cfc f a) at most one, and cfc f (cfc g b)=b for every self-adjoint contraction b. Along any filter, pointwise strong convergence of self-adjoint operators to a self-adjoint operator is preserved by cfc f. No uniform norm bound on the approximating operators is assumed. The difference identity with rho(t)=(1+t squared) inverse and tau(t)=t/(1+t squared), whose calculus norms are at most one and one half, supplies the convergence estimate.")),
        Describe.Lean(DescribeId.Create("statement0"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/CStarAlgebra/ContinuousFunctionalCalculus/Kaplansky.kaplanskyFun_def"),
            H("kaplanskyFun_def"), StatementSource.FromAuthor(Disp(Statement0())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Unfold kaplanskyFun: the defining real rational function has numerator 2t and denominator 1+t squared. This definitional identity is the rewriting input for the range bound and inverse calculation."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement1"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/CStarAlgebra/ContinuousFunctionalCalculus/Kaplansky.kaplanskyFunInv_def"),
            H("kaplanskyFunInv_def"), StatementSource.FromAuthor(Disp(Statement1())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Unfold kaplanskyFunInv: its denominator is 1 plus the nonnegative real square root of 1-s squared. The identity fixes the chosen inverse branch used in kaplanskyFun_kaplanskyFunInv."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement2"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/CStarAlgebra/ContinuousFunctionalCalculus/Kaplansky.continuous_inv_one_add_sq"),
            H("continuous_inv_one_add_sq"), StatementSource.FromAuthor(Disp(Statement2())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The function 1+t squared is continuous by continuous_pow and continuous addition. The helper one_add_sq_pos excludes zero at every real t, so Continuous.inv₀ makes its reciprocal continuous."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement3"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/CStarAlgebra/ContinuousFunctionalCalculus/Kaplansky.continuous_div_one_add_sq"),
            H("continuous_div_one_add_sq"), StatementSource.FromAuthor(Disp(Statement3())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Both the identity numerator and 1+t squared denominator are continuous. The strict positivity supplied by one_add_sq_pos permits Continuous.div, giving continuity without restricting t."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement4"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/CStarAlgebra/ContinuousFunctionalCalculus/Kaplansky.continuous_kaplanskyFun"),
            H("continuous_kaplanskyFun"), StatementSource.FromAuthor(Disp(Statement4())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The numerator 2t is continuous, as is the polynomial denominator. Since one_add_sq_pos excludes denominator zeros, Continuous.div proves continuity of kaplanskyFun on the whole real line."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement5"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/CStarAlgebra/ContinuousFunctionalCalculus/Kaplansky.continuous_kaplanskyFunInv"),
            H("continuous_kaplanskyFunInv"), StatementSource.FromAuthor(Disp(Statement5())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Continuous.sqrt applies to the continuous real function 1-s squared, even outside the unit interval. Its square root is nonnegative, so adding 1 gives a strictly positive denominator; Continuous.div proves continuity of the inverse formula everywhere."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement6"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/CStarAlgebra/ContinuousFunctionalCalculus/Kaplansky.abs_kaplanskyFun_le_one"),
            H("abs_kaplanskyFun_le_one"), StatementSource.FromAuthor(Disp(Statement6())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Rewrite the absolute value of the rational expression using kaplanskyFun_def and the positive denominator one_add_sq_pos. The resulting inequality 2 abs(t) at most 1+t squared follows from nonnegativity of (abs(t)-1) squared and sq_abs."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement7"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/CStarAlgebra/ContinuousFunctionalCalculus/Kaplansky.kaplanskyFun_kaplanskyFunInv"),
            H("kaplanskyFun_kaplanskyFunInv"), StatementSource.FromAuthor(Disp(Statement7())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("From abs(s) at most 1 derive 1-s squared nonnegative. Real.sq_sqrt supplies the square-root identity and Real.sqrt_nonneg makes the inverse denominator nonzero. Substitute kaplanskyFun_def and kaplanskyFunInv_def, clear denominators, and use that square-root identity to reduce the rational expression to s."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement8"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/CStarAlgebra/ContinuousFunctionalCalculus/Kaplansky.abs_div_one_add_sq_le"),
            H("abs_div_one_add_sq_le"), StatementSource.FromAuthor(Disp(Statement8())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The positive denominator one_add_sq_pos allows multiplication of the desired bound by 1+t squared. After abs_div and sq_abs, the inequality follows from nonnegativity of (abs(t)-1) squared, as in the bound for kaplanskyFun."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement9"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/CStarAlgebra/ContinuousFunctionalCalculus/Kaplansky.cfc_one_add_sq"),
            H("cfc_one_add_sq"), StatementSource.FromAuthor(Disp(Statement9())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Use cfc_const_add to split the constant and square terms, then cfc_pow_id for the square. Algebra.algebraMap_eq_smul_one and one_smul identify the constant functional calculus value with the algebra unit."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement10"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/CStarAlgebra/ContinuousFunctionalCalculus/Kaplansky.cfc_div_one_add_sq_eq_mul"),
            H("cfc_div_one_add_sq_eq_mul"), StatementSource.FromAuthor(Disp(Statement10())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Rewrite scalar division as inverse times t using div_eq_inv_mul, and transfer that equality through cfc_congr. Then cfc_mul, with continuous_inv_one_add_sq, separates the factors, and cfc_id' identifies the identity-function factor with a."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement11"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/CStarAlgebra/ContinuousFunctionalCalculus/Kaplansky.cfc_div_one_add_sq_eq_mul_left"),
            H("cfc_div_one_add_sq_eq_mul_left"), StatementSource.FromAuthor(Disp(Statement11())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Use div_eq_mul_inv and cfc_congr to put t first. cfc_mul separates it from the reciprocal factor, using continuous_id and continuous_inv_one_add_sq; cfc_id' then gives a times the reciprocal functional calculus value. This supplies the opposite product order needed by the difference identity."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement12"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/CStarAlgebra/ContinuousFunctionalCalculus/Kaplansky.cfc_kaplanskyFun_eq_smul"),
            H("cfc_kaplanskyFun_eq_smul"), StatementSource.FromAuthor(Disp(Statement12())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Pointwise kaplanskyFun_def rewrites the scalar function as twice t/(1+t squared). cfc_smul, justified by continuous_div_one_add_sq, moves this scalar multiple outside the functional calculus; cfc_congr matches the two scalar expressions."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement13"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/CStarAlgebra/ContinuousFunctionalCalculus/Kaplansky.cfc_kaplanskyFun_sub_cfc_kaplanskyFun"),
            H("cfc_kaplanskyFun_sub_cfc_kaplanskyFun"), StatementSource.FromAuthor(Disp(Statement13())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Use cfc_kaplanskyFun_eq_smul and the two product-order formulas for cfc_div_one_add_sq. The inverse and direct values of cfcUnits for 1+t squared multiply to 1, and cfc_one_add_sq identifies the direct factors. Insert these two units into the difference; expanding while preserving factor order yields the stated noncommutative identity, without assuming a and b commute."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement14"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/CStarAlgebra/ContinuousFunctionalCalculus/Kaplansky.norm_cfc_kaplanskyFun_le"),
            H("norm_cfc_kaplanskyFun_le"), StatementSource.FromAuthor(Disp(Statement14())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The scalar estimate abs_kaplanskyFun_le_one bounds the function on every spectral value. Apply norm_cfc_le with nonnegative bound 1 to obtain the operator norm estimate; the total functional calculus convention also covers elements outside the self-adjoint predicate."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement15"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/CStarAlgebra/ContinuousFunctionalCalculus/Kaplansky.norm_cfc_inv_one_add_sq_le"),
            H("norm_cfc_inv_one_add_sq_le"), StatementSource.FromAuthor(Disp(Statement15())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Since 1+t squared is at least 1, its positive reciprocal is at most 1 by inv_le_one_of_one_le₀. With one_add_sq_pos this bounds the absolute value at every real spectral value, and norm_cfc_le transfers the bound to the algebra."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement16"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/CStarAlgebra/ContinuousFunctionalCalculus/Kaplansky.norm_cfc_div_one_add_sq_le"),
            H("norm_cfc_div_one_add_sq_le"), StatementSource.FromAuthor(Disp(Statement16())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Apply norm_cfc_le with the nonnegative bound one half. The scalar bound on every spectral value is exactly abs_div_one_add_sq_le, so the same bound holds for its functional calculus value."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement17"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/CStarAlgebra/ContinuousFunctionalCalculus/Kaplansky.cfc_kaplanskyFun_cfc_kaplanskyFunInv"),
            H("cfc_kaplanskyFun_cfc_kaplanskyFunInv"), StatementSource.FromAuthor(Disp(Statement17())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Use cfc_comp to compose the two continuous scalar functions. For each spectral value s of b, norm_apply_le_norm_cfc applied to the identity function bounds abs(s) by norm(b), hence by 1. kaplanskyFun_kaplanskyFunInv therefore identifies the composition with the identity on the spectrum; cfc_congr and cfc_id' recover b."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement18"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/TauCeti/Analysis/CStarAlgebra/ContinuousFunctionalCalculus/Kaplansky.tendsto_cfc_kaplanskyFun_apply"),
            H("tendsto_cfc_kaplanskyFun_apply"), StatementSource.FromAuthor(Disp(Statement18())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Fix the vectors w1=rho(y)v and w2=sigma(y)v, with rho(t)=1/(1+t squared) and sigma(t)=t/(1+t squared). The difference identity bounds the norm of the desired difference eventually by 2 times (norm(x(i)w1-yw1)+one half times norm(x(i)w2-yw2)), using norm_cfc_inv_one_add_sq_le and norm_cfc_div_one_add_sq_le. Both errors tend to zero by the given pointwise convergence, so squeeze_zero' proves convergence along the original filter without a uniform norm bound on x(i)."))), DescribeRole.Theorem))));

